import java.sql.*;import java.nio.file.*;import java.util.*;import com.fasterxml.jackson.databind.*;
/** Read-only actual ADJ runtime inventory; no plaintext model/material, JWT, passwords or sessions exported. */
class AuditAdjudicationProductRuntime {
 static String env(String n){String v=System.getenv(n);if(v==null||v.isBlank())throw new IllegalArgumentException("Missing private audit setting: "+n);return v;}
 static List<Map<String,Object>> rows(Connection c,String sql)throws Exception {try(var s=c.createStatement()){s.setQueryTimeout(20);try(var r=s.executeQuery(sql)){var out=new ArrayList<Map<String,Object>>();while(r.next()){var row=new LinkedHashMap<String,Object>();for(int i=1;i<=r.getMetaData().getColumnCount();i++){Object v=r.getObject(i);if(v instanceof java.sql.Clob clob){if(clob.length()>100000)throw new IllegalStateException("Source rights payload too large");v=clob.getSubString(1,(int)clob.length());}row.put(r.getMetaData().getColumnLabel(i),v instanceof java.sql.Timestamp?v.toString():v);}out.add(row);}return out;}}}
 public static void main(String[] args)throws Exception {
  if(args.length!=1)throw new IllegalArgumentException("Evidence output required");Class.forName("dm.jdbc.driver.DmDriver");var json=new ObjectMapper();var result=new LinkedHashMap<String,Object>();result.put("scope","READ_ONLY_ACTUAL_ADJ_IDENTITY_CASE_MODEL_AUDIT_NOT_REAL_PERSON_OR_PROFESSIONAL_ACCEPTANCE");result.put("checkedAtUtc",java.time.Instant.now().toString());
  try(var c=DriverManager.getConnection("jdbc:dm://127.0.0.1:5301","ADJLLM20261003",env("ADJ_PRODUCT_AUDIT_PASSWORD"))){c.setReadOnly(true);var budget=rows(c,"SELECT case_id,approval_key,policy_key,calls,input_tokens,output_tokens,cost_micros,frozen,expires_at FROM adj3_model_budget");result.put("modelBudget",budget);String expected=System.getenv("ADJ_PRODUCT_AUDIT_EXPECT_CALLS");if(expected!=null && (budget.size()!=1||((Number)budget.getFirst().get("CALLS")).longValue()!=Long.parseLong(expected)))throw new IllegalStateException("Persistent cumulative allowance differs; no provider call allowed");result.put("subjects",rows(c,"SELECT issuer,subject_id,login_name,subject_kind,status,credential_version FROM id2_subject WHERE issuer='https://localhost:5445'"));result.put("grants",rows(c,"SELECT grant_id,issuer,subject_id,organization,domain_code,task_scope,data_scope,resource_id,action_code,purpose,status,grant_version,expires_at FROM id2_grant WHERE domain_code='ADJUDICATION'"));result.put("activeSessionCount",rows(c,"SELECT COUNT(*) AS session_count FROM id2_session WHERE issuer='https://localhost:5445' AND status='ACTIVE' AND expires_at>CURRENT_TIMESTAMP"));result.put("caseHeads",rows(c,"SELECT case_id,organization,data_scope,head_version,head_sha256 FROM adj2_case_work"));result.put("caseAuditVersions",rows(c,"SELECT case_id,work_version,input_version,actor_ref,action_code,created_at FROM adj2_case_revision ORDER BY case_id,work_version"));result.put("modelRuns",rows(c,"SELECT run_id,policy_key,request_key,actor_ref,state,input_tokens,output_tokens,cost_micros,created_at,expires_at,payload_sha FROM adj3_material_run ORDER BY created_at"));}
  try(var c=DriverManager.getConnection("jdbc:dm://127.0.0.1:5370","ADJAUTH20261004",env("ADJ_PRODUCT_AUDIT_AUTHORITY_PASSWORD"))){c.setReadOnly(true);result.put("maintainer",rows(c,"SELECT subject_ref,organization,certificate_sha,allowed_roles,status,version FROM id2_maintainer"));result.put("authorityWatermark",rows(c,"SELECT issuer,generation,state,history_sha FROM id2_authority_watermark"));result.put("maintenanceAudit",rows(c,"SELECT subject_ref,certificate_sha,role_code,decision,occurred_at FROM id2_maintenance_audit ORDER BY occurred_at"));result.put("sourceGeneration",rows(c,"SELECT generation,state FROM adj2_source_generation"));var uses=rows(c,"SELECT source_key,case_id,organization,data_scope,state,version,payload FROM adj2_source_use ORDER BY source_key");for(var u:uses){var n=json.readTree((String)u.remove("PAYLOAD"));u.put("source",n.path("source"));u.put("allowedUses",n.path("allowedUses"));u.put("validUntil",n.path("validUntil"));u.put("evidenceRef",n.path("evidenceRef"));u.put("evidenceSha256",n.path("evidenceSha256"));}result.put("sourceUses",uses);result.put("sourceEvents",rows(c,"SELECT source_key,version,action_code,maintainer_ref,occurred_at FROM adj2_source_event ORDER BY occurred_at"));}
  Files.writeString(Path.of(args[0]),json.writerWithDefaultPrettyPrinter().writeValueAsString(result));System.out.println("ACTUAL_ADJ_READ_ONLY_INVENTORY_EXPORTED_NO_SECRETS_OR_MODEL_PLAINTEXT");
 }
}
